    "seat": "平城→洛陽（北朝）/ 建康（南朝）",
    "summary": "420 年劉裕代晉建宋，南朝歷宋、齊、梁、陳；北方北魏太武帝拓跋燾先後滅胡夏（431）、北燕（436）、北涼（439），於 439 年正式統一北方，結束五胡十六國。534 年北魏分裂為東魏、西魏，又分別為北齊、北周所代。拖動底部時間軸可檢視各階段疆域演變。",
